bash -lc python - <<'PY'
from pptx import Presentation
for f in ['A_Folio_Magazine_EXACT_STORY.pptx','B_Swiss_Grid_EXACT_STORY.pptx','C_Investigative_Dossier_EXACT_STORY.pptx','D_Studio_Type_EXACT_STORY.pptx']:
 p=Presentation('/mnt/data/runtime_story_editable/'+f)
 print(f)
 for i in [0,4,5]:
  slide=p.slides[i]
  for sh in slide.shapes:
   if sh.has_text_frame and ('Remember when' in sh.text or 'The agent had made' in sh.text or 'Then came' in sh.text):
    pp=sh.text_frame.paragraphs[0]
    print(i+1, 'runs',[(r.font.name,r.font.size.pt if r.font.size else None, r.font.bold) for r in pp.runs], 'font',pp.font.name,pp.font.size.pt if pp.font.size else None)
PY
